using KennelPro.Interfaces.Litters; using KennelPro.Models.Litters; using KennelPro.Validators;
namespace KennelPro.Services.Reproduction;
public class PuppyService { readonly IPuppyRepository _repo; readonly LitterService _litters; public PuppyService(IPuppyRepository repo,LitterService litters){_repo=repo;_litters=litters;} public async Task<List<Puppy>> GetForLitterAsync(Guid id)=>await _litters.GetByIdAsync(id)==null?new():(await _repo.GetByLitterIdAsync(id)).ToList(); public async Task<Puppy?> GetByIdAsync(Guid id){var x=await _repo.GetByIdAsync(id);return x!=null&&await _litters.GetByIdAsync(x.LitterId)!=null?x:null;} public async Task<(bool,string)> AddAsync(Puppy x){if(await _litters.GetByIdAsync(x.LitterId)==null)return(false,"Litter not found.");x.Id=x.Id==Guid.Empty?Guid.NewGuid():x.Id;if(!PuppyValidator.Validate(x,out var e))return(false,e);await _repo.AddAsync(x);return(true,"");} public async Task<(bool,string)> UpdateAsync(Puppy x){var old=await GetByIdAsync(x.Id);if(old==null)return(false,"Puppy not found.");x.LitterId=old.LitterId;if(!PuppyValidator.Validate(x,out var e))return(false,e);await _repo.UpdateAsync(x);return(true,"");} public async Task<bool> DeleteAsync(Guid id){if(await GetByIdAsync(id)==null)return false;await _repo.DeleteAsync(id);return true;} }
